draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // head
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 150);
  ctx.lineWidth = 3;
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2 - 50, H/2 + 120);
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2 + 50, H/2 + 120);
  ctx.lineWidth = 3;
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150);
  ctx.lineTo(W/2 - 30, H/2 + 200);
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150);
  ctx.lineTo(W/2 + 30, H/2 + 200);
  ctx.lineWidth = 3;
  ctx.stroke();

  // food
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 80, H/2 + 50, 20, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // chew
  ctx.beginPath();
  ctx.arc(W/2 - 80, H/2 + 50, 10 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.restore();
}
